def transform(grid):
    h, w = len(grid), len(grid[0])

    def mode(values):
        counts = {}
        for v in values:
            counts[v] = counts.get(v, 0) + 1
        return max(counts, key=counts.get)

    # Separator rows and columns are the regularly spaced lines with a
    # dominant color; marker colors may replace a few cells at intersections.
    row_modes = [mode(row) for row in grid]
    row_lines = [r for r, color in enumerate(row_modes)
                 if sum(v == color for v in grid[r]) >= 0.75 * w]

    col_modes = []
    for c in range(w):
        col_modes.append(mode([grid[r][c] for r in range(h)]))
    col_lines = []
    for c, color in enumerate(col_modes):
        if sum(grid[r][c] == color for r in range(h)) >= 0.75 * h:
            col_lines.append(c)

    # The common interior color is the default output color.
    interior = []
    for r in range(h):
        if r not in row_lines:
            for c in range(w):
                if c not in col_lines:
                    interior.append(grid[r][c])
    default = mode(interior)

    # Determine the main separator color from the line modes.
    sep_color = mode([row_modes[r] for r in row_lines] +
                     [col_modes[c] for c in col_lines])

    out = []
    for i in range(len(row_lines) - 1):
        row = []
        for j in range(len(col_lines) - 1):
            corners = [
                grid[row_lines[i]][col_lines[j]],
                grid[row_lines[i]][col_lines[j + 1]],
                grid[row_lines[i + 1]][col_lines[j]],
                grid[row_lines[i + 1]][col_lines[j + 1]],
            ]
            v = corners[0]
            row.append(v if v != sep_color and all(x == v for x in corners)
                       else default)
        out.append(row)

    # Ignore rows or columns containing only the default output.
    while out and all(v == default for v in out[-1]):
        out.pop()
    while out and all(v == default for v in out[0]):
        out.pop(0)
    while out and all(row[-1] == default for row in out):
        for row in out:
            row.pop()
    while out and all(row[0] == default for row in out):
        for row in out:
            row.pop(0)
    return out
